import backend.dao.UserDAO; import backend.model.User; public class TestLogin { public static void main(String[] args) throws Exception { UserDAO dao = new UserDAO(); try { User u = dao.login("student1", "student123"); if(u != null) { System.out.println("Success! " + u.getUsername() + ", Role: " + u.getRole()); } else { System.out.println("Failed to login"); } } catch (Exception e) { e.printStackTrace(); } } }
